    entry_requirements = '<h4>Pre-requisites</h4><div> <div> <div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><p>There are no specific prerequisites specified in the training package for BSB80120 – Graduate Diploma of Management Learning qualification. Want to know more about this course then <a href="https://asia.edu.au/contact-us-astral-skills-institute-of-australia/">contact us</a>.</p></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div> </div> </div><h4>RTO Requirements for International students</h4><div> <div> <div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><p>International students applying for this <a href="https://asia.edu.au/courses/">course</a>, whether offshore or onshore, must meet certain English language requirements:</p><ul><li>Be at least 18 years of age and have completed the equivalent of Year 12.</li><li>Participate in a course entry interview to assess suitability and student needs.</li><li>Have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:</li><li>Education for 5 years in an English-speaking country; or</li><li>Successful completion of an English Placement Test.</li></ul><p>*Note that other English language tests such as PTE and TOEFL may be accepted. Students must provide their results to confirm their equivalence to <a href="https://en.wikipedia.org/wiki/International_English_Language_Testing_System">IELTS</a> 6.0.</p></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div> </div> </div>',
    apply_form = 'https://asia.edu.au/bsb80120-graduate-diploma-of-management-learning/',
    updated_at = NOW()
