    entry_requirements = '<h4>Pre-requisites</h4><div> <div> <div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><p>To enroll in this qualification, you must meet one of the following criteria:</p><ul><li>Hold a <a href="https://asia.edu.au/certificate-iii-in-early-childhood-education-and-care/">CHC30121 Certificate III in Early Childhood Education and Care</a> or</li><li>Hold a CHC30113 Certificate III in Early Childhood Education and Care.</li></ul></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div> </div> </div><h4>RTO Requirements for International students</h4><div> <div> <p>International students must fulfill certain English language requirements for admission into ASIA:</p> <ul><li>Be at least 18 years old and have completed Year 12 or an equivalent qualification.</li> <li>Participate in a course entry interview to assess suitability and needs.</li> <li>Obtain an IELTS* score of 6.0 (results should be within 2 years). Other English language tests like PTE and TOEFL may also be accepted. The results should be equivalent to IELTS 6.0.</li> </ul><p>Additional information on student visa assessment levels can be found on the <a href="https://www.homeaffairs.gov.au/">Department of Home Affairs (DHA)</a> website.</p> </div> </div>',
